import React, { useState } from 'react';
import type { Plan, GroundingSource } from '../types';
import { LoadingSpinner } from './LoadingSpinner';
import { 
    AnalysisIcon, 
    FlowIcon, 
    StackIcon, 
    RocketIcon, 
    StatsIcon, 
    SearchIcon,
    DocumentArrowDownIcon,
    FloppyIcon,
    PencilIcon,
    CheckIcon
} from './icons';
import { jsPDF } from 'jspdf';

interface AutomationPlanProps {
    plan: Plan | null;
    sources: GroundingSource[];
    isLoading: boolean;
    refs: any;
    onSaveProject: () => void;
    currentProjectId: string | null;
    onUpdateSection: (sectionKey: keyof Plan, newContent: string) => void;
}

const Card: React.FC<{ 
    title: string; 
    content: string; 
    icon: React.ReactNode; 
    isLoading: boolean;
    idRef: React.RefObject<HTMLDivElement | null>;
    onSaveContent: (newContent: string) => void;
}> = ({ title, content, icon, isLoading, idRef, onSaveContent }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [editedContent, setEditedContent] = useState(content);

    // Sincronizar contenido si cambia externamente (ej: regeneración)
    React.useEffect(() => {
        setEditedContent(content);
    }, [content]);

    const handleSave = () => {
        onSaveContent(editedContent);
        setIsEditing(false);
    };

    return (
        <div ref={idRef} className="bg-gray-800/40 rounded-2xl border border-gray-800 shadow-xl overflow-hidden backdrop-blur-sm group hover:border-gray-700 transition-colors">
            <div className="border-b border-gray-800 px-6 py-4 flex items-center justify-between bg-gray-800/20">
                <h3 className="text-lg font-bold flex items-center gap-3 text-white">
                    <span className="text-cyan-500 bg-cyan-500/10 p-2 rounded-lg">{icon}</span>
                    {title}
                </h3>
                <div className="flex items-center gap-2">
                    {isLoading && <LoadingSpinner />}
                    {!isLoading && content && (
                        <button
                            onClick={() => isEditing ? handleSave() : setIsEditing(true)}
                            className={`p-2 rounded-lg transition-all ${
                                isEditing 
                                ? 'bg-green-600/20 text-green-400 hover:bg-green-600/30' 
                                : 'bg-gray-800 text-gray-400 hover:text-white hover:bg-gray-700'
                            }`}
                            title={isEditing ? "Guardar cambios" : "Remodelar / Editar"}
                        >
                            {isEditing ? <CheckIcon className="w-4 h-4" /> : <PencilIcon className="w-4 h-4" />}
                        </button>
                    )}
                </div>
            </div>
            <div className="p-8">
                {isLoading && !content ? (
                     <div className="py-12 flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl">
                        <p className="text-sm italic">Pendiente de generación...</p>
                    </div>
                ) : isEditing ? (
                    <textarea
                        value={editedContent}
                        onChange={(e) => setEditedContent(e.target.value)}
                        className="w-full h-96 bg-gray-900/50 border border-gray-700 rounded-xl p-4 text-gray-300 font-mono text-sm leading-relaxed focus:ring-2 focus:ring-cyan-500/30 outline-none resize-y"
                    />
                ) : content ? (
                    <div className="prose prose-invert max-w-none prose-p:text-gray-400 prose-p:leading-relaxed prose-li:text-gray-400 prose-strong:text-cyan-400">
                        {content.split('\n').map((paragraph, index) => {
                            if (paragraph.startsWith('- ') || paragraph.startsWith('* ')) {
                                return <li key={index} className="mb-2 list-none flex gap-2">
                                    <span className="text-cyan-600">•</span> {paragraph.substring(2)}
                                </li>;
                            }
                            if (/^\d+\./.test(paragraph)) {
                                 return <li key={index} className="mb-2 list-none flex gap-2">
                                    <span className="font-bold text-cyan-600">{paragraph.split('.')[0]}.</span> {paragraph.substring(paragraph.indexOf('.')+1)}
                                </li>;
                            }
                            return paragraph.trim() ? <p key={index} className="mb-4">{paragraph}</p> : null;
                        })}
                    </div>
                ) : (
                    <div className="py-12 flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl">
                        <p className="text-sm italic">Esperando datos...</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export const AutomationPlan: React.FC<AutomationPlanProps> = ({ 
    plan, 
    sources, 
    isLoading, 
    refs, 
    onSaveProject, 
    currentProjectId,
    onUpdateSection 
}) => {
    const handleExportPDF = () => {
        if (!plan) return;
        const doc = new jsPDF();
        let y = 20;
        const leftMargin = 20;
        const pageWidth = doc.internal.pageSize.width;
        const maxLineWidth = pageWidth - (leftMargin * 2);

        doc.setFontSize(22);
        doc.text("Plan de Automatización", leftMargin, y);
        y += 15;

        const sections = [plan.analysis, plan.flows, plan.stack, plan.implementation, plan.roi];
        sections.forEach(section => {
            if (!section.title || !section.content) return;
            doc.setFontSize(16);
            doc.setTextColor(0, 100, 160);
            doc.text(section.title, leftMargin, y);
            y += 10;
            doc.setFontSize(11);
            doc.setTextColor(20, 20, 20);
            const lines = doc.splitTextToSize(section.content, maxLineWidth);
            lines.forEach((line: string) => {
                if (y > 280) { doc.addPage(); y = 20; }
                doc.text(line, leftMargin, y);
                y += 6;
            });
            y += 10;
        });

        doc.save("plan_automatizacion.pdf");
    };

    return (
        <div className="space-y-12">
            <div className="flex flex-col sm:flex-row justify-between items-center bg-gray-900/90 p-6 rounded-2xl border border-gray-800 gap-4 sticky top-0 z-10 backdrop-blur-xl shadow-lg">
                <div>
                    <h2 className="text-2xl font-bold text-white flex items-center gap-3">
                        Resultados de Auditoría
                        {currentProjectId && <span className="text-xs px-2 py-1 bg-green-500/20 text-green-400 rounded-full border border-green-500/30">Modo Edición</span>}
                    </h2>
                    <p className="text-gray-500 text-sm">Visualiza, remodela y exporta tu estrategia.</p>
                </div>
                <div className="flex gap-3">
                    <button 
                        onClick={onSaveProject}
                        disabled={!plan}
                        className={`flex items-center px-5 py-2.5 rounded-xl transition-all border text-sm font-bold shadow-lg ${
                            currentProjectId 
                            ? 'bg-green-600 hover:bg-green-500 text-white border-green-500' 
                            : 'bg-cyan-600 hover:bg-cyan-500 text-white border-cyan-500'
                        } disabled:opacity-50 disabled:cursor-not-allowed disabled:bg-gray-800 disabled:border-gray-700 disabled:text-gray-500`}
                    >
                        <FloppyIcon className="w-5 h-5 mr-2" />
                        {currentProjectId ? 'Actualizar Proyecto' : 'Guardar Proyecto'}
                    </button>
                    <button 
                        onClick={handleExportPDF}
                        disabled={!plan}
                        className="flex items-center px-5 py-2.5 bg-gray-800 hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-xl transition-all border border-gray-700 shadow-lg text-sm font-semibold"
                    >
                        <DocumentArrowDownIcon className="w-5 h-5 mr-2 text-gray-400" />
                        Exportar PDF
                    </button>
                </div>
            </div>

            <Card 
                idRef={refs.analysis}
                title="1. Análisis de Procesos Manuales" 
                content={plan?.analysis.content || ''} 
                icon={<AnalysisIcon />} 
                isLoading={isLoading && !plan}
                onSaveContent={(c) => onUpdateSection('analysis', c)}
            />

            <Card 
                idRef={refs.flows}
                title="2. Diseño de Flujos de Agentes" 
                content={plan?.flows.content || ''} 
                icon={<FlowIcon />} 
                isLoading={isLoading && !plan}
                onSaveContent={(c) => onUpdateSection('flows', c)}
            />

            <Card 
                idRef={refs.stack}
                title="3. Stack Tecnológico Recomendado" 
                content={plan?.stack.content || ''} 
                icon={<StackIcon />} 
                isLoading={isLoading && !plan}
                onSaveContent={(c) => onUpdateSection('stack', c)}
            />

            <Card 
                idRef={refs.implementation}
                title="4. Implementación Paso a Paso" 
                content={plan?.implementation.content || ''} 
                icon={<RocketIcon />} 
                isLoading={isLoading && !plan}
                onSaveContent={(c) => onUpdateSection('implementation', c)}
            />

            <Card 
                idRef={refs.roi}
                title="5. ROI Estimado" 
                content={plan?.roi.content || ''} 
                icon={<StatsIcon />} 
                isLoading={isLoading && !plan}
                onSaveContent={(c) => onUpdateSection('roi', c)}
            />

            <div ref={refs.sources} className="bg-gray-800/40 rounded-2xl border border-gray-800 shadow-xl overflow-hidden backdrop-blur-sm">
                <div className="border-b border-gray-800 px-6 py-4 bg-gray-800/20">
                    <h3 className="text-lg font-bold flex items-center gap-3 text-white">
                        <span className="text-cyan-500 bg-cyan-500/10 p-2 rounded-lg"><SearchIcon /></span>
                        Fuentes de Información
                    </h3>
                </div>
                <div className="p-8">
                    {sources.length > 0 ? (
                        <ul className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {sources.map((source, index) => (
                                <li key={index} className="flex">
                                    <a 
                                        href={source.uri} 
                                        target="_blank" 
                                        rel="noopener noreferrer" 
                                        className="flex-1 p-4 bg-gray-900/50 border border-gray-800 rounded-xl hover:border-cyan-500/50 hover:bg-gray-800 transition-all group"
                                    >
                                        <p className="text-cyan-400 font-medium text-sm mb-1 group-hover:underline truncate">{source.title}</p>
                                        <p className="text-gray-500 text-xs truncate">{source.uri}</p>
                                    </a>
                                </li>
                            ))}
                        </ul>
                    ) : (
                        <div className="py-12 flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl">
                            <p className="text-sm italic">Esperando búsqueda externa...</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import { GoogleGenAI, Chat, Schema, Type } from "@google/genai";
import type { ChatMessage, GroundingSource, Plan } from '../types';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const planGenerationModel = 'gemini-3-pro-preview';
const chatModel = 'gemini-3-flash-preview';

let chat: Chat | null = null;

// Esquema de respuesta JSON estricto
const planSchema: Schema = {
    type: Type.OBJECT,
    properties: {
        analysis: { type: Type.STRING, description: "Contenido detallado para Análisis de Procesos Manuales en Markdown." },
        flows: { type: Type.STRING, description: "Contenido detallado para Diseño de Flujos de Agentes en Markdown." },
        stack: { type: Type.STRING, description: "Contenido detallado para Stack Tecnológico Recomendado en Markdown." },
        implementation: { type: Type.STRING, description: "Contenido detallado para Implementación Paso a Paso en Markdown." },
        roi: { type: Type.STRING, description: "Contenido detallado para ROI Estimado en Markdown. Debe centrarse exclusivamente en ahorro de costes, tiempo y beneficios económicos." },
    },
    required: ["analysis", "flows", "stack", "implementation", "roi"],
};

export const generateAutomationPlan = async (businessDescription: string): Promise<{ planData: any, sources: GroundingSource[] }> => {
    const prompt = `
Eres un experto consultor en automatización de clase mundial.
Analiza esta descripción de negocio: "${businessDescription}"

Genera un plan de automatización completo. 
IMPORTANTE:
1. Usa formato Markdown dentro de los campos JSON para listas, negritas, etc.
2. En la sección 'roi', asegúrate de hablar SOLO de retorno de inversión, tiempos ahorrados y métricas. NO hables de características técnicas o modelos de voz en esta sección.
3. Utiliza Google Search para fundamentar tus recomendaciones.
`;

    try {
        const response = await ai.models.generateContent({
            model: planGenerationModel,
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: planSchema,
                thinkingConfig: { thinkingBudget: 1024 }, // Thinking reducido para priorizar formato
                tools: [{ googleSearch: {} }],
            },
        });

        const jsonText = response.text || "{}";
        const planData = JSON.parse(jsonText);

        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
        const sources: GroundingSource[] = groundingChunks
            .map((chunk: any) => ({
                uri: chunk.web?.uri || '',
                title: chunk.web?.title || 'Fuente de información'
            }))
            .filter((source: GroundingSource) => source.uri);

        return { planData, sources };
    } catch (error) {
        console.error("Gemini API Error (generateAutomationPlan):", error);
        throw new Error("Error al conectar con la IA de Gemini.");
    }
};

export const chatWithBot = async (history: ChatMessage[], newMessage: string): Promise<string> => {
    try {
        if (!chat) {
            chat = ai.chats.create({
                model: chatModel,
                config: {
                    systemInstruction: 'Eres un asistente experto en automatización de procesos empresariales. Responde de forma concisa y profesional.',
                },
                history: history.map(msg => ({
                    role: msg.role,
                    parts: [{ text: msg.content }]
                })),
            });
        }

        const response = await chat.sendMessage({ message: newMessage });
        return response.text || "No pude generar una respuesta.";
    } catch (error) {
        console.error("Gemini API Error (chatWithBot):", error);
        chat = null; 
        throw new Error("Error en la comunicación del chat.");
    }
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { Header } from './components/Header';
import { BusinessInput } from './components/BusinessInput';
import { AutomationPlan } from './components/AutomationPlan';
import { AdminPanel } from './components/AdminPanel';
import { ChatBot } from './components/ChatBot';
import { SaveModal } from './components/SaveModal';
import { generateAutomationPlan } from './services/geminiService';
import type { Plan, GroundingSource, SavedPlan, PlanSection } from './types';

const STORAGE_KEY = 'automation_hub_database_v2';

const App: React.FC = () => {
    const [automationPlan, setAutomationPlan] = useState<Plan | null>(null);
    const [groundingSources, setGroundingSources] = useState<GroundingSource[]>([]);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [isAdminOpen, setIsAdminOpen] = useState<boolean>(true);
    const [history, setHistory] = useState<SavedPlan[]>([]);
    const [currentDescription, setCurrentDescription] = useState<string>('');
    const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);

    // UI States
    const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);
    const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

    const sectionsRefs = {
        input: useRef<HTMLDivElement>(null),
        analysis: useRef<HTMLDivElement>(null),
        flows: useRef<HTMLDivElement>(null),
        stack: useRef<HTMLDivElement>(null),
        implementation: useRef<HTMLDivElement>(null),
        roi: useRef<HTMLDivElement>(null),
        sources: useRef<HTMLDivElement>(null),
    };

    useEffect(() => {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
            try {
                setHistory(JSON.parse(saved));
            } catch (e) {
                console.error("Error loading database", e);
            }
        }
    }, []);

    useEffect(() => {
        if (notification) {
            const timer = setTimeout(() => setNotification(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [notification]);

    const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
        setNotification({ message, type });
    };

    const saveToStorage = (newHistory: SavedPlan[]) => {
        try {
            setHistory(newHistory);
            localStorage.setItem(STORAGE_KEY, JSON.stringify(newHistory));
        } catch (e) {
            console.error("Error saving to localStorage", e);
            showNotification("Error: Almacenamiento lleno", 'error');
        }
    };

    const scrollToSection = (sectionId: keyof typeof sectionsRefs) => {
        sectionsRefs[sectionId].current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    };

    const handleNewAudit = () => {
        setAutomationPlan(null);
        setGroundingSources([]);
        setCurrentDescription('');
        setCurrentProjectId(null);
        scrollToSection('input');
    };

    const loadFromHistory = (savedPlan: SavedPlan) => {
        setAutomationPlan(savedPlan.plan);
        setGroundingSources(savedPlan.sources);
        setCurrentDescription(savedPlan.businessDescription);
        setCurrentProjectId(savedPlan.id);
        setTimeout(() => scrollToSection('analysis'), 100);
    };

    const handleDeleteProject = (id: string) => {
        if (window.confirm('¿Estás seguro de que deseas eliminar este proyecto de la base de datos?')) {
            const updatedHistory = history.filter(item => item.id !== id);
            saveToStorage(updatedHistory);
            if (currentProjectId === id) {
                handleNewAudit();
            }
            showNotification("Proyecto eliminado");
        }
    };

    const handleSaveButtonClick = () => {
        if (!automationPlan) return;
        if (currentProjectId) {
            updateExistingProject();
        } else {
            setIsSaveModalOpen(true);
        }
    };

    const updateExistingProject = () => {
        if (!currentProjectId || !automationPlan) return;

        const updatedHistory = history.map(p => {
            if (p.id === currentProjectId) {
                return {
                    ...p,
                    timestamp: Date.now(),
                    businessDescription: currentDescription,
                    plan: automationPlan,
                    sources: groundingSources
                };
            }
            return p;
        });
        saveToStorage(updatedHistory);
        showNotification("Proyecto actualizado correctamente");
    };

    const handleSaveNewProject = (name: string) => {
        if (!automationPlan) return;

        const newId = Date.now().toString();
        const savedItem: SavedPlan = {
            id: newId,
            name: name,
            timestamp: Date.now(),
            businessDescription: currentDescription,
            plan: automationPlan,
            sources: groundingSources
        };

        const updatedHistory = [savedItem, ...history];
        saveToStorage(updatedHistory);
        setCurrentProjectId(newId);
        setIsSaveModalOpen(false);
        showNotification("Nuevo proyecto guardado en Base de Datos");
    };

    const handleUpdatePlanSection = (sectionKey: keyof Plan, newContent: string) => {
        if (!automationPlan) return;
        setAutomationPlan({
            ...automationPlan,
            [sectionKey]: {
                ...automationPlan[sectionKey],
                content: newContent
            }
        });
    };

    const handleImportProject = (file: File) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const content = e.target?.result as string;
                const importedPlan = JSON.parse(content) as SavedPlan;

                if (!importedPlan.plan || !importedPlan.id) {
                    throw new Error("Formato de archivo inválido");
                }

                importedPlan.id = Date.now().toString() + Math.random().toString().slice(2, 5);
                importedPlan.name = importedPlan.name + " (Importado)";

                const updatedHistory = [importedPlan, ...history];
                saveToStorage(updatedHistory);
                loadFromHistory(importedPlan);
                showNotification("Proyecto importado correctamente");
            } catch (err) {
                console.error("Error importing file:", err);
                showNotification("Error al importar el archivo", 'error');
            }
        };
        reader.readAsText(file);
    };

    const handleGeneratePlan = useCallback(async (businessDescription: string) => {
        if (!businessDescription.trim()) {
            setError("Por favor, describe tu negocio.");
            return;
        }
        setIsLoading(true);
        setError(null);
        setAutomationPlan(null);
        setGroundingSources([]);
        setCurrentDescription(businessDescription);

        try {
            // Ahora devuelve un objeto JSON estructurado
            const result = await generateAutomationPlan(businessDescription);
            const { planData, sources } = result;

            const newPlan: Plan = {
                analysis: { title: '1. Análisis de Procesos Manuales', content: planData.analysis || '' },
                flows: { title: '2. Diseño de Flujos de Agentes', content: planData.flows || '' },
                stack: { title: '3. Stack Tecnológico Recomendado', content: planData.stack || '' },
                implementation: { title: '4. Implementación Paso a Paso', content: planData.implementation || '' },
                roi: { title: '5. ROI Estimado', content: planData.roi || '' },
            };

            setAutomationPlan(newPlan);
            setGroundingSources(sources);

        } catch (err) {
            console.error("Error generating plan:", err);
            setError("Hubo un error al generar el plan. Por favor, inténtalo de nuevo.");
        } finally {
            setIsLoading(false);
        }
    }, []);

    return (
        <div className="h-screen bg-gray-950 text-gray-100 font-sans flex flex-col overflow-hidden">
            <Header onToggleAdmin={() => setIsAdminOpen(!isAdminOpen)} isAdminOpen={isAdminOpen} />

            {/* Notifications */}
            <div className={`fixed top-20 right-1/2 translate-x-1/2 z-50 transition-all duration-300 transform ${notification ? 'translate-y-0 opacity-100' : '-translate-y-10 opacity-0 pointer-events-none'}`}>
                {notification && (
                    <div className={`px-6 py-3 rounded-full shadow-2xl border flex items-center gap-3 backdrop-blur-md ${
                        notification.type === 'success' 
                        ? 'bg-green-500/10 border-green-500/50 text-green-400' 
                        : 'bg-red-500/10 border-red-500/50 text-red-400'
                    }`}>
                        <div className={`w-2 h-2 rounded-full ${notification.type === 'success' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                        <span className="font-semibold text-sm">{notification.message}</span>
                    </div>
                )}
            </div>

            <SaveModal 
                isOpen={isSaveModalOpen} 
                onClose={() => setIsSaveModalOpen(false)} 
                onSave={handleSaveNewProject} 
            />

            <div className="flex flex-1 overflow-hidden relative">
                <AdminPanel 
                    isOpen={isAdminOpen} 
                    onNavigate={scrollToSection} 
                    hasPlan={!!automationPlan}
                    history={history}
                    onLoadPlan={loadFromHistory}
                    onNewAudit={handleNewAudit}
                    onImportProject={handleImportProject}
                    onDeleteProject={handleDeleteProject}
                    currentProjectId={currentProjectId}
                />

                {/* 
                   MODIFICACIÓN IMPORTANTE: 
                   Se ha eliminado el padding global (p-4 md:p-8) de <main> para permitir 
                   que el sticky header de AutomationPlan llegue a los bordes.
                   Se añade padding local a los componentes hijos.
                */}
                <main className="flex-1 overflow-y-auto bg-gray-900/30 pb-32 custom-scrollbar relative">
                    {/* Wrapper con padding para la sección de Input */}
                    <div className="p-4 md:p-8 space-y-8 max-w-7xl mx-auto">
                        <div ref={sectionsRefs.input}>
                            <BusinessInput 
                                onGenerate={handleGeneratePlan} 
                                isLoading={isLoading} 
                                initialValue={currentDescription}
                            />
                        </div>

                        {error && (
                            <div className="bg-red-900/30 border border-red-800 text-red-200 px-6 py-4 rounded-xl text-center backdrop-blur-md">
                                {error}
                            </div>
                        )}
                    </div>

                    {/* AutomationPlan maneja su propio layout y sticky header */}
                    <AutomationPlan 
                        plan={automationPlan}
                        sources={groundingSources}
                        isLoading={isLoading}
                        refs={sectionsRefs}
                        onSaveProject={handleSaveButtonClick}
                        currentProjectId={currentProjectId}
                        onUpdateSection={handleUpdatePlanSection}
                    />
                </main>
            </div>

            <ChatBot />
        </div>
    );
};

export default App;

import React, { useState } from 'react';
import type { Plan, GroundingSource } from '../types';
import { LoadingSpinner } from './LoadingSpinner';
import { 
    AnalysisIcon, 
    FlowIcon, 
    StackIcon, 
    RocketIcon, 
    StatsIcon, 
    SearchIcon,
    DocumentArrowDownIcon,
    FloppyIcon,
    PencilIcon,
    CheckIcon
} from './icons';
import { jsPDF } from 'jspdf';

interface AutomationPlanProps {
    plan: Plan | null;
    sources: GroundingSource[];
    isLoading: boolean;
    refs: any;
    onSaveProject: () => void;
    currentProjectId: string | null;
    onUpdateSection: (sectionKey: keyof Plan, newContent: string) => void;
}

const Card: React.FC<{ 
    title: string; 
    content: string; 
    icon: React.ReactNode; 
    isLoading: boolean;
    idRef: React.RefObject<HTMLDivElement | null>;
    onSaveContent: (newContent: string) => void;
